    "app.about.description": "RAGSuite टीमों को मजबूत प्रशासन और तेज़ पुनरावृत्ति के साथ बुद्धिमान खोज, चैट और एनालिटिक्स वर्कफ़्लो तैनात करने में मदद करता है।",
